parameters.text:
=You are a dedicated recipe assistant bot operating in a Slack workspace. Your sole purpose is to provide cooking recipes to users in valid JSON format.

Strictly follow these guidelines for every incoming message:
1. **Validate the Request**: Check if the user's input is asking for a recipe, dish, or cooking instructions.
2. **Handle Non-Recipe Input**: If the user's input is unrelated to food or recipes, do not answer with a recipe. Instead, return a JSON response containing this exact message:
{
  "message": "Please ask for a recipe, I am unable to assist with other requests."
}
3. **Format Recipe Responses**: If the user requests a valid recipe, you must return your response strictly as a valid JSON object matching this exact schema:
{
  "ingredients_required": [
    "Ingredient 1 - 5tps or required quantity",
    "Ingredient 2 - 1tps or required quantity"
  ],
  "procedure": [
    "step 1: Put oil in pan",
    "step 2: throw curry leaves"
  ]
}

Ensure your output is strictly valid JSON with no extra conversational text outside of the JSON structure.

user prompt :  {{ $json.text }}

parameters.jsCode:
for (const item of $input.all()) {
  // Get raw text from the previous LLM node (adjust 'text' or 'message' if needed)
  let rawText = item.json.text || item.json.message || item.json; 
  let parsedData = {};

  // Step 1: Clean and Parse JSON string
  if (typeof rawText === 'string') {
    let cleanedText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    try {
      parsedData = JSON.parse(cleanedText);
    } catch (error) {
      item.json = { 
        error: "Failed to parse JSON string", 
        details: error.message, 
        raw: rawText,
        slackMessage: "Sorry, I encountered an error processing your recipe request."
      };
      continue;
    }
  } else {
    parsedData = rawText;
  }

  // Step 2: Handle non-recipe validation messages
  if (parsedData.message) {
    item.json = {
      ...parsedData,
      slackMessage: parsedData.message
    };
    continue;
  }

  // Step 3: Format the recipe data into a Slack-friendly message
  let ingredients = parsedData.ingredients_required || [];
  let procedure = parsedData.procedure || [];

  let ingredientsText = ingredients.map(ing => `• ${ing}`).join('\n');
  let procedureText = procedure.map(step => `> ${step}`).join('\n');

  let slackMessage = `*Here is your recipe:* \n\n` +
                     `*Ingredients Required:*\n${ingredientsText}\n\n` +
                     `*Step-by-Step Procedure:*\n${procedureText}`;

  // Step 4: Output both the parsed JSON structure and the ready-to-use slack message
  item.json = {
    ...parsedData,
    slackMessage: slackMessage
  };
}

return $input.all();
